package com.wanyuecity.energy.operation;
import com.wanyuecity.energy.core.ApiResponse;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/v1/operations/property-inspections") public class OperationPropertyInspectionController{private final OperationPropertyInspectionService s;public OperationPropertyInspectionController(OperationPropertyInspectionService s){this.s=s;}@GetMapping@PreAuthorize("hasAnyRole('SUPER_ADMIN','SYSTEM_ADMIN','APPLICANT','DEVICE_VERIFIER')")public ApiResponse<List<Map<String,Object>>>records(@RequestParam(defaultValue="")String periodDate){return ApiResponse.ok(s.records(periodDate));}@GetMapping("/templates")@PreAuthorize("hasAnyRole('SUPER_ADMIN','SYSTEM_ADMIN','DEVICE_VERIFIER')")public ApiResponse<List<Map<String,Object>>>templates(){return ApiResponse.ok(s.templates());}@GetMapping("/templates/stall/{token}")@PreAuthorize("hasAnyRole('SUPER_ADMIN','SYSTEM_ADMIN','DEVICE_VERIFIER')")public ApiResponse<Map<String,Object>>resolve(@PathVariable String token){return ApiResponse.ok(s.resolve(token));}@PostMapping("/templates")@PreAuthorize("hasAnyRole('SUPER_ADMIN','SYSTEM_ADMIN')")public ApiResponse<Map<String,Object>>save(@RequestBody Map<String,Object>b,Authentication a){return ApiResponse.ok(s.saveTemplate(b,a.getName()));}@PutMapping("/templates/{id}/enable")@PreAuthorize("hasAnyRole('SUPER_ADMIN','SYSTEM_ADMIN')")public ApiResponse<Void>enable(@PathVariable Long id){s.enableTemplate(id);return ApiResponse.ok(null);}@PostMapping("/stall/{token}")@PreAuthorize("hasAnyRole('SUPER_ADMIN','SYSTEM_ADMIN','DEVICE_VERIFIER')")public ApiResponse<Map<String,Object>>submit(@PathVariable String token,@RequestBody Map<String,Object>b,Authentication a){return ApiResponse.ok(s.submit(token,b,a.getName()));}}
